    65  static void close_var_refs(JSRuntime *rt, JSFunctionBytecode *b, JSStackFrame *sf)
    66  {
    67      JSVarRef *var_ref;
    68      int i;
    69
    70      for(i = 0; i < b->var_ref_count; i++) {
    71          var_ref = sf->var_refs[i];
    72          if (var_ref)
    73              close_var_ref(rt, sf, var_ref);
    74      }
    75  }
